const motifCategory = id => {
 const decorative = new Set(['vine','lily','grapes','branch','spiral','rope','zigzag','arcade','column','shingles','spiral-chevron','interlaced-diamonds','wave-scroll','wave-palmette','rosette-chain','crossed-circles','t-bar-border','linked-wheels'])
 const figurative = new Set(['horse','radimlja-figure-extract','museum-horse-rider','kolo','deer','raised-hand','bird','boar','snake','dog','winged-horse'])
 return decorative.has(id) ? 'Decorative' : figurative.has(id) ? 'Figurative' : 'Symbolic'
}
